sp_widget.client_script:
api.controller = function($scope, $location, $window) {
    var c = this;

    c.searchQuery = '';
    c.statusFilter = '';

    // --- Pagination Setup ---
    c.currentPage = 1;
    c.itemsPerPage = 9; // Adjust this to show however many cards you want per page

    $scope.filterPrograms = function(program) {
        var matchesSearch = !c.searchQuery ||
            (program.name && program.name.toLowerCase().indexOf(c.searchQuery.toLowerCase()) > -1) ||
            (program.description && program.description.toLowerCase().indexOf(c.searchQuery.toLowerCase()) > -1);

        var matchesStatus = !c.statusFilter || program.status === c.statusFilter;

        return matchesSearch && matchesStatus;
    };
    c.goBack = function() {
      // UPDATED TO USE $window FOR ABSOLUTE URLS
      $window.location.href = 'https://enablenowincdemo1.service-now.com/applicant?id=applicant_dashboard';
  };
    // --- Pagination Logic ---
    // Reset to page 1 whenever user searches or filters
    $scope.$watchGroup(['c.searchQuery', 'c.statusFilter'], function() {
        c.currentPage = 1;
    });

    // Set active page
    c.changePage = function(page) {
        c.currentPage = page;
    };

    // Calculate total pages based on current active filters
    c.totalPages = function(totalItems) {
        return Math.ceil(totalItems / c.itemsPerPage);
    };

    // Return array of numbers to repeat pagination buttons
    c.getPages = function(totalItems) {
        var pages = [];
        var total = c.totalPages(totalItems);
        for (var i = 1; i <= total; i++) {
            pages.push(i);
        }
        return pages;
    };

    // Provide angular with math evaluation for the 'Showing X to Y' string
    c.getMathMin = function(a, b) {
        return Math.min(a, b);
    };

     c.viewDetails = function(sysId) {
        // Redirects to your new page and passes the program's sys_id in the URL
        $location.url('?id=program_dashboard_detail&sys_id=' + sysId);
    };
}

sp_widget.css:
.browse-programs-widget {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  padding: 24px;
  background: #f5f6fa;
  min-height: 100vh;
  margin-top:3%;
}

/* Header */
.bp-header { margin-bottom: 20px; }
.bp-title { font-size: 24px; font-weight: 700; color: #1a1a2e; margin: 0 0 4px; }
.bp-subtitle { font-size: 14px; color: #666; margin: 0; }

/* Toolbar */
.bp-toolbar {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}
.bp-search-wrap, .bp-filter-wrap {
  display: flex;
  align-items: center;
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  padding: 8px 14px;
  gap: 8px;
}
.bp-search-wrap { flex: 1; }
.bp-filter-wrap { min-width: 180px; }
.bp-search-input, .bp-filter-select {
  border: none;
  outline: none;
  font-size: 14px;
  color: #333;
  background: transparent;
  width: 100%;
}

/* Grid */
.bp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

/* Card */
.bp-card {
  background: #fff;
  border-radius: 12px;
  padding: 20px 22px 18px;
  border: 1px solid #e8e8e8;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  transition: box-shadow 0.2s;
}
.bp-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.10); }

/* Top Row */
.bp-card-toprow {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.bp-grant-type { font-size: 12px; color: #888; }

/* Badge */
.bp-badge {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
  border: 1.5px solid;
}
.bp-badge-accepting {
  color: #2ecc71;
  border-color: #2ecc71;
  background: #f0fff6;
}
.bp-badge-upcoming {
  color: #9b59b6;
  border-color: #9b59b6;
  background: #f9f0ff;
}
.bp-badge-closed {
  color: #e74c3c;
  border-color: #e74c3c;
  background: #fff5f5;
}

/* Card Content */
.bp-card-title {
  font-size: 17px;
  font-weight: 700;
  color: #1a1a2e;
  margin: 0;
}
.bp-card-desc {
  font-size: 13px;
  color: #555;
  line-height: 1.5;
  margin: 0;
}

/* Meta */
.bp-card-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #444;
}
.bp-meta-amount { font-weight: 600; color: #1a1a2e; }
.bp-meta-sep { color: #bbb; }
.bp-meta-awards { color: #555; }
.bp-card-deadline { color: #666; }

/* Button */
.bp-btn-view {
  margin-top: 6px;
  background: linear-gradient(135deg, #3D3180, #5443AD, #6B5FBF);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px;
  width: 100%;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s;
}

.bp-btn-view:hover {
  background: linear-gradient(135deg, #6a35aa, #4a2278);
  box-shadow: 0 4px 12px rgba(91, 45, 142, 0.35);
}


/* Empty */
.bp-empty { text-align: center; color: #aaa; padding: 40px; grid-column: 1/-1; }

/* Responsive */
@media (max-width: 768px) {
  .bp-grid { grid-template-columns: 1fr; }
  .bp-toolbar { flex-direction: column; }
}
/* ── Pagination ── */
.bp-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 28px;
  padding: 0 4px;
  flex-wrap: wrap;
  gap: 12px;
}

.bp-page-info {
  font-size: 13px;
  color: #666;
}

.bp-page-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bp-page-btn {
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid #e0e0e0;
  background: #fff;
  border-radius: 8px;
  font-size: 14px;
  color: #333;
  cursor: pointer;
  transition: all 0.2s;
}

.bp-page-btn:hover:not([disabled]) {
  background: #f0f3ff;
  border-color: #2d4de0;
  color: #2d4de0;
}

.bp-page-btn[disabled] {
  opacity: 0.35;
  cursor: not-allowed;
}

.bp-page-btn.bp-page-active {
  background: #2d4de0;
  color: #fff;
  border-color: #2d4de0;
  font-weight: 700;
}

/* Back Button */
.bp-btn-back {
  background: #fff;
  color: #333;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 8px; /* Spaces the SVG icon and text */
}

.bp-btn-back:hover {
  background: #f0f3ff;
  border-color: #2d4de0;
  color: #2d4de0;
}
// BREADCRUMB
// ===========================
.detail-breadcrumb {
  display: flex;
  align-items: center;
  gap: 10px;               // ← increased gap between all items including arrows
  margin-bottom:2px;
  margin-top: -8px;        // ← nudges it up slightly without breaking flow
  font-size: 13px;
}

.breadcrumb-link {
  color: #666;
  text-decoration: none;
  font-weight: 500;
  transition: color 0.2s;

  &:hover {
    color: #2d4de0;
  }
}

.breadcrumb-sep {
  color: #bbb;
  font-size: 12px;
  line-height: 1;
  padding: 0 2px;          // ← adds breathing room on both sides of the arrow
}

.breadcrumb-current {
  color: #1a1a2e;
  font-weight: 600;
}
/* Category Tag */
.bp-category-tag {
  font-size: 11px;
  font-weight: 600;
  color: #7b3fc4;
  background: #f3ecfc;
  border: 1px solid #d4b3f0;
  border-radius: 20px;
  padding: 3px 10px;
}

/* Meta label/value pairs */
.bp-meta-label {
  font-size: 12px;
  color: #888;
  font-weight: 500;
}

.bp-meta-value {
  font-size: 13px;
  color: #1a1a2e;
  font-weight: 600;
}
/* ═══════════════════════════════════════
   LAYOUT — sidebar + main content
═══════════════════════════════════════ */
.gn-layout {
  display: flex;
  min-height: 100vh;
  background: #f0f2f5;
}

.sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border-right: 5px solid #e5e7eb;
  position: sticky;
  top: 2%;
  height: 100vh;
  overflow-y: auto;
  z-index: 10;
  margin-top:-2%;
}

sp_widget.script:
(function() {
		data.sideBar = $sp.getWidget('sidebar_dashboard');
    data.programs = [];

    var gr = new GlideRecord('x_enno_gatenow_grant_program');
    var qc = gr.addQuery('status', 'accepting_proposals');
    qc.addOrCondition('status', 'published');
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {
        data.programs.push({
            sys_id:         gr.getUniqueValue(),
            name:           gr.getDisplayValue('program_name'),
            description:    gr.getDisplayValue('short_description'),
            status:         gr.status.getDisplayValue(),
            total_funding:  gr.getValue('program_budget'),
            close_date:     gr.getValue('proposal_close_date'),
            award_type:     gr.getDisplayValue('award_type'),       // ← new
            open_date:      gr.getValue('proposal_open_date'),      // ← new
            category:       gr.getDisplayValue('category')          // ← new
        });
    }
})();
